code.C:
#include <stdio.h>
int main() {
    char s[1005]; if (scanf("%s", s) != 1) return 0;
    long long prod = 1;
    for (int i = 0; s[i]; i++) prod *= (s[i] - '0');
    printf("%lld\n", prod);
    return 0;
}

