code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next();
            long prod = 1;
            for (char c : s.toCharArray()) prod *= (c - '0');
            System.out.println(prod);
        }
    }
}

